SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) BETWEEN 49 AND 59 AND admissions.admission_type_id = 172757 AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = admissions.subject_id AND diagnoses_icd.icd_code = '42601');